function ParkourBossMain:GetUpBuffData()
    local data = {}
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    for i, v in ipairs(self.data.upGroup) do
        local hasCard = cardComp:IsHasCard(v.refId)
        local tempData = {}
        tempData.refId = v.refId
        tempData.type = v.type
        local index = 1
        if hasCard then
            local cardDojo = cardComp:GetCardByConfId(v.refId)
            local star = cardDojo.star
            index = star + 1

        end
        tempData.commonAddId = v.additions[index].commonAddId
        table.insert(data,tempData)
    end
    return data
end

--region init
function ParkourBossMain:InitHandler()
    self.bossHandler = Events.AddListener("BOSS_DMG_REWARD", function(rewardId)
        if self.data then
            if checkNumber(rewardId) == 0 then
                -- 1. 获取所有奖励
                local allRewards = CfUtils.GetCf(AutoIds.IdSetting6453, "ActivityCakeBossHurtVo", true)
                -- 2. 获取所有可领取但未领取的奖励
                local allCanDrawButNotInListRewards = {}
                local historyMaxHurt = checkNumber(self.data.playerRank.damage)
                for i, reward in ipairs(allRewards) do
                    ---@type MidFestivalBossDamageRewardVo
                    local rewardVo = reward
                    if checkNumber(historyMaxHurt) >= checkNumber(rewardVo.upperLimit) and (not table.isContain(self.data.receivedDamageRewardIds, rewardVo.id, function(id, cId) return checkNumber(id) == checkNumber(cId)  end)) then
                        table.insert(allCanDrawButNotInListRewards, rewardVo)
                    end
                end
                -- 3. 将他们全部设置为已领取
                for _, rewardVo in ipairs(allCanDrawButNotInListRewards) do
                    table.insert(self.data.receivedDamageRewardIds,rewardVo.id)
                end
            else
                if not not table.isContain(self.data.receivedDamageRewardIds, rewardId, function(id, cId) return checkNumber(id) == checkNumber(cId)  end) then
                    table.insert(self.data.receivedDamageRewardIds, rewardId)
                end
            end
            ---如果有小红点的逻辑
            self:IsHaveDMGRewards()
        end
    end)
    SetButtonAction(self.Btncheck, Bind(self, self.OnBtnBossDetailClickHandler))
    SetButtonAction(self.BtnList, Bind(self, self.OnBtnListClickHandler))
    SetButtonAction(self.BtnReward, Bind(self, self.OnBtnHurtRewardClickHandler))
    --CfUtils.SetActive(self.BtnReward, false)
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnFightHandler))
    SetButtonAction(self.FontStyleButton.transform.parent:Find("BtnDetails"), function()
        local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
        ---@type ActivityCakeBosScheduleVo
        local scheduleVo = CfUtils.GetCfVo(AutoIds.IdSetting6456, "ActivityCakeBosScheduleVo", activityContentId)
        ---@type ActivityCakeBossLevelVo
        local questVo = CfUtils.GetCfVo(AutoIds.IdSetting6454, "ActivityCakeBossLevelVo", scheduleVo.range)

        UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaParkourDropMessagePopUp, parameters = { data = self.data.showRewards, desc = questVo.desc } })
    end)
    ---@type ParkourBossMainRankNode
    self._playerRankScr = CfUtils.GetLuaScr(self.WorldBossPlayerRankingsDialog, "Game.Activity.ParkourGame.Dialog.ParkourBossMainRankNode")
    self:FreshConsumePopup()
end

function ParkourBossMain:FreshConsumePopup()
    self.AlignNode = self.FontStyleButton.transform.parent:Find("AlignNode")
    if isNull(self.AlignNode) then
        return
    end
    local times = checkInt(KCookie.Get("MINI_BOSS_CONSUME"))
    if times == 0 then
        times = 1
    end
    ---@type CommonFilter
    local lt = CfUtils.GetLuaScr(self.AlignNode.gameObject, "Game.UI.Common.CommonFilter")
    if isNotNull(lt) then
        KTool.SetActive(self.AlignNode, true)
        local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
        ---@type ActivityCakeBosScheduleVo
        local scheduleVo = CfUtils.GetCfVo(AutoIds.IdSetting6456, "ActivityCakeBosScheduleVo", activityContentId)
        ---@type ActivityCakeBossLevelVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting6454, "ActivityCakeBossLevelVo", scheduleVo.range)
        if isNull(vo) then
            printError("id %s 找不到关卡信息", scheduleVo.range)
            return
        end
        local costItem = vo.costItem
        local costNum = (vo.costNum + vo.costNumLose)
        ---@type MidFestivalBossParameterVo
        local parametersVo =  CfUtils.GetCfVo(AutoIds.IdSetting6452, "ActivityCakeBossParamsVo", 18)
        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(costItem)
        if isNull(goodsVo) then
            printError("id %s 找不到道具信息", costItem)
            return
        end

        local p = string.split(parametersVo.num, ";")
        -- 构造列表数据
        local filterData = {}
        for _i, v in ipairs(p) do
            local data = {
                imgPath = goodsVo.photoPath,
                text1 = localize("_num_倍", {_num_ = v}),
                text2 = tostring(costNum * checkInt(v))
            }
            table.insert(filterData, data)
        end
        self.times = times
        lt:SetOnValueChanged(function(index)
            self.times = index
        end)
        lt:RefreshPanel(filterData, self.times)
    end
end

function ParkourBossMain:InitData()
    --self._planVo = ActivityCakeUtils.GetActivityBossScheduleVo(1)
    --self._questVo = ActivityCakeUtils.GetActivityBossLevelVo(self._planVo.range)
    GameUtils.BindRedPoint(Constants.RedPointConst.MainActivityMinWorldBoss, self.BtnReward, true)
    local success = false
    GameUtils.Request("activityTinyWorld/boss", { activityUuid = self.activityData.id }, function(request, response)
        success = true
        if checkInt(response.errCode) == 0 then
            local responseData = response.data
            self.data = responseData
            if isNull(self.data.upGroup) then
                self.data.upGroup = {}
            end
            --self.data.playerRank.damage = 100000
            self:RefreshUI()
            self:IsHaveDMGRewards()
        end
    end)

    while not success do
        coroutine.yield()
    end
end
