function ParkourBossMain:OnBtnFightHandler()
    ---@type PlayerComponent
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
    local endTime = checkNumber(self.activityData.endTime)
    local leftTime = endTime - curDate
    if leftTime <= 0 then
        return GameUtils.Toast(localize("活动已经结束"))
    end
    local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
    ---@type ActivityCakeBosScheduleVo
    local scheduleVo = CfUtils.GetCfVo(AutoIds.IdSetting6456, "ActivityCakeBosScheduleVo", activityContentId)
    KCookie.Set("MINI_BOSS_CONSUME", checkInt(self.times))
    CfUtils.DialogOpen(Constants.UITypeIds.UIFightTeamChoose, { activityUuid = self.activityData.id,
                                                                levelId = scheduleVo.range, upBuffData = self:GetUpBuffData(),upGroup = self.data.upGroup }, { { id = Constants.UITypeIds.ParkourBossMain } })
end

function ParkourBossMain:OnBtnBossDetailClickHandler()
    local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
    ---@type ActivityCakeBosScheduleVo
    local scheduleVo = CfUtils.GetCfVo(AutoIds.IdSetting6456, "ActivityCakeBosScheduleVo", activityContentId)
    ---@type ActivityCakeBossLevelVo
    local questVo = CfUtils.GetCfVo(AutoIds.IdSetting6454, "ActivityCakeBossLevelVo", scheduleVo.range)
    CfUtils.DialogOpen(Constants.UITypeIds.ParkourBossDetailDialog, { planVo = scheduleVo, questVo = questVo }, { { id = Constants.UITypeIds.ParkourBossMain } })
end

