--region private
function ParkourBossMain:RefreshPlayerRank()
    local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
    local function GetRemainTime(timestamp)
        ---@type PlayerComponent
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if not comp then return 0 end
        local curTime = comp:GetPlayerDojo():GetServerTime()
        curTime = curTime or os.time()
        local seconds = checkInt(timestamp) - curTime
        if seconds <= 0 then
            return 0, localize("活动已结束")
        end
        return seconds
    end
    self._playerRankScr:Refresh(self.data, activityContentId, checkInt(self.activityData.id), GetRemainTime(checkNumber(self.activityData.closeTime)))
end

function ParkourBossMain:IsHaveDMGRewards()
    --是否存在未领取的逻辑
    -- 1. 获取所有奖励
    local allRewards = CfUtils.GetCf(AutoIds.IdSetting6453, "ActivityCakeBossHurtVo", true)
    -- 2. 获取所有可领取但未领取的奖励
    local allCanDrawButNotInListRewards = {}
    local historyMaxHurt = checkNumber(self.data.playerRank.damage)
    for i, reward in ipairs(allRewards) do
        ---@type MidFestivalBossDamageRewardVo
        local rewardVo = reward
        if checkNumber(historyMaxHurt) >= checkNumber(rewardVo.upperLimit) and (not table.isContain(self.data.receivedDamageRewardIds, rewardVo.id, function(id, cId) return checkNumber(id) == checkNumber(cId)  end)) then
            table.insert(allCanDrawButNotInListRewards, rewardVo)
        end
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.MainActivityMinWorldBoss, #allCanDrawButNotInListRewards > 0 and 1 or 0)
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.MainActivityMinWorldBoss)
end

function ParkourBossMain:RefreshUI()
    local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
    ---@type ActivityCakeBosScheduleVo
    local scheduleVo = CfUtils.GetCfVo(AutoIds.IdSetting6456, "ActivityCakeBosScheduleVo", activityContentId)
    CfUtils.FillImage(self.Bg, scheduleVo.modelId)

    self.lineUpInfo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(scheduleVo.range)
    for _, line in ipairs(self.lineUpInfo) do
        local ids = line.wave1NpcId
        for index, id in ipairs(ids) do
            local vo = CardConfMgr:GetInstance():GetMonsterTypeVoById(id)
            if checkNumber(vo.monsterClass) == Constants.RoleClass.Boss then
                local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(vo.skinId)
                CfUtils.FillText(self.TxtName, skinVo.name)
            end
        end
    end

    CfUtils.RefreshTopGoods({})

    self:RefreshPlayerRank()
    self:FreshRoleBuffInfo()
end
